/**
 * The header a Harness-owned conversation identity travels on, under the same
 * name `dsh-llm-deepseek` sends on its own provider requests. A gateway that
 * recognizes the Harness as a client routes and prompt-caches per conversation
 * from it, and opencode.ai answers a request without it with HTTP 400
 * `MissingSessionID`.
 */
const HARNESS_SESSION_HEADER = 'x-deepseek-harness-session-id'

/**
 * Merge deployment headers, the Harness session header, and attribution into
 * one provider request header set.
 *
 * A profile entry naming the session header is overridden rather than trusted:
 * the value must name the conversation this request belongs to, which only the
 * request knows. Attribution names are Harness-owned and win collisions for the
 * same reason.
 * @param headers - deployment headers configured on the route.
 * @param sessionId - the conversation to name, or undefined when the route did not opt in or the caller named none.
 * @returns the headers to send.
 */
function requestHeaders(
  headers: Readonly<Record<string, string>> | undefined,
  sessionId: string | undefined,
): Record<string, string> {
  const attribution = attributionHeaders()
  const reserved = new Set(Object.keys(attribution).map(name => name.toLowerCase()))
  return {
    ...Object.fromEntries(Object.entries(headers ?? {}).filter(([name]) => !reserved.has(name.toLowerCase()))),
    ...sessionId === undefined ? {} : { [HARNESS_SESSION_HEADER]: sessionId },
    ...attribution,
  }
}

