it('sends the Harness session header on an opted-in route, overriding a profile entry of the same name', async () => {
  const server = await mockServer([{ events: textEvents }])
  const ctx = await harness(server.url, {
    harnessSessionHeader: true,
    headers: { 'x-deepseek-harness-session-id': 'stale-from-config' },
  })
  await assemble(ctx, {
    model: 'deepseek-v4-flash',
    messages: [],
    sessionId: 'session-live' as never,
  })
  expect(server.headers[0]?.['x-deepseek-harness-session-id']).toBe('session-live')
})

it('omits the Harness session header without the route opt-in or a caller session', async () => {
  const notOptedIn = await mockServer([{ events: textEvents }])
  await assemble(await harness(notOptedIn.url), {
    model: 'deepseek-v4-flash',
    messages: [],
    sessionId: 'session-unused' as never,
  })
  expect(notOptedIn.headers[0]).not.toHaveProperty('x-deepseek-harness-session-id')

  const noCallerSession = await mockServer([{ events: textEvents }])
  await assemble(await harness(noCallerSession.url, { harnessSessionHeader: true }), {
    model: 'deepseek-v4-flash',
    messages: [],
  })
  expect(noCallerSession.headers[0]).not.toHaveProperty('x-deepseek-harness-session-id')
})

