/**
 * Read the deployment's display-copy table, keyed by exact package name.
 *
 * The global name is a private agreement between this manager and the
 * deployment's own client plugins; it is absent in every shipped profile. An
 * unset or mistyped table yields no entries rather than an error, so the
 * shipped derivation in {@link packageText} stays the fallback.
 * @returns the published table, or an empty object when none is published.
 */
function deploymentCopy(): Record<string, { title: string; description?: string }> {
  const table = (globalThis as { __DSH_PLUGIN_COPY__?: unknown }).__DSH_PLUGIN_COPY__
  return table !== null && typeof table === 'object' && !Array.isArray(table)
    ? table as Record<string, { title: string; description?: string }>
    : {}
}
